//! VIL Metrics — System metrics collection plugin.
//!
//! This plugin provides real-time system metrics including CPU, memory, disk,
//! and network statistics. Designed for VIL's zero-copy architecture.

pub mod collector;
pub mod error;
pub mod metrics;
pub mod plugin;

pub use collector::MetricsCollector;
pub use error::MetricsError;
pub use metrics::{CpuMetrics, DiskMetrics, MemoryMetrics, NetworkMetrics, SystemSnapshot};
pub use plugin::SystemMetricsPlugin;

//! Error types for VIL Metrics.

use thiserror::Error;

/// Errors that can occur in the metrics subsystem.
#[derive(Debug, Error)]
pub enum MetricsError {
    /// Failed to collect system metrics.
    #[error("collection failed: {0}")]
    CollectionFailed(String),

    /// Invalid metric configuration.
    #[error("invalid configuration: {0}")]
    InvalidConfig(String),

    /// Storage error (e.g., retention policy).
    #[error("storage error: {0}")]
    StorageError(String),
}

//! System metrics data structures.

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};

/// A point-in-time snapshot of all system metrics.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SystemSnapshot {
    /// Timestamp of the snapshot.
    pub timestamp: DateTime<Utc>,
    /// CPU metrics.
    pub cpu: CpuMetrics,
    /// Memory metrics.
    pub memory: MemoryMetrics,
    /// Disk metrics.
    pub disk: DiskMetrics,
    /// Network metrics.
    pub network: NetworkMetrics,
}

/// CPU utilization metrics.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CpuMetrics {
    /// Overall CPU usage percentage (0-100).
    pub usage_percent: f32,
    /// Per-core usage percentages.
    pub per_core_usage: Vec<f32>,
    /// Number of CPU cores.
    pub core_count: usize,
    /// CPU frequency in MHz (if available).
    pub frequency_mhz: Option<u64>,
    /// CPU brand/model string.
    pub brand: String,
}

/// Memory utilization metrics.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MemoryMetrics {
    /// Total physical memory in bytes.
    pub total_bytes: u64,
    /// Used memory in bytes.
    pub used_bytes: u64,
    /// Available memory in bytes.
    pub available_bytes: u64,
    /// Usage percentage (0-100).
    pub usage_percent: f32,
    /// Swap/VM memory in bytes.
    pub swap_bytes: u64,
}

/// Disk metrics.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DiskMetrics {
    /// Per-disk information.
    pub disks: Vec<DiskInfo>,
}

/// Information about a single disk/volume.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DiskInfo {
    /// Mount point (e.g., "/", "/home").
    pub mount_point: String,
    /// Filesystem type (e.g., "ext4", "ntfs").
    pub fs_type: String,
    /// Total disk space in bytes.
    pub total_bytes: u64,
    /// Used disk space in bytes.
    pub used_bytes: u64,
    /// Available disk space in bytes.
    pub available_bytes: u64,
    /// Usage percentage (0-100).
    pub usage_percent: f32,
}

/// Network interface metrics.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NetworkMetrics {
    /// Per-interface network statistics.
    pub interfaces: Vec<NetworkInterface>,
}

/// Network interface statistics.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NetworkInterface {
    /// Interface name (e.g., "eth0", "wlan0").
    pub name: String,
    /// Received bytes since boot.
    pub rx_bytes: u64,
    /// Transmitted bytes since boot.
    pub tx_bytes: u64,
    /// Packets received.
    pub rx_packets: u64,
    /// Packets transmitted.
    pub tx_packets: u64,
    /// RX errors.
    pub rx_errors: u64,
    /// TX errors.
    pub tx_errors: u64,
}

//! Metrics collector implementation.

use super::error::MetricsError;
use super::metrics::{CpuMetrics, DiskInfo, DiskMetrics, NetworkInterface, NetworkMetrics, SystemSnapshot};
use chrono::Utc;
use std::sync::Arc;
use sysinfo::{Disks, Networks, System};
use tokio::sync::RwLock;
use tokio::time::{Duration, Interval};

/// Configuration for the metrics collector.
#[derive(Debug, Clone)]
pub struct CollectorConfig {
    /// Polling interval for metrics collection.
    pub poll_interval: Duration,
    /// Whether to include per-core CPU metrics.
    pub per_core_metrics: bool,
    /// Whether to track network interfaces.
    pub network_tracking: bool,
}

impl Default for CollectorConfig {
    fn default() -> Self {
        Self {
            poll_interval: Duration::from_secs(5),
            per_core_metrics: true,
            network_tracking: true,
        }
    }
}

/// Collector for system metrics.
/// Maintains internal state and provides periodic snapshots.
pub struct MetricsCollector {
    config: CollectorConfig,
    system: Arc<RwLock<System>>,
    networks: Arc<RwLock<Networks>>,
    disks: Arc<RwLock<Disks>>,
}

impl MetricsCollector {
    /// Create a new collector with default configuration.
    pub fn new() -> Self {
        Self::with_config(CollectorConfig::default())
    }

    /// Create a new collector with custom configuration.
    pub fn with_config(config: CollectorConfig) -> Self {
        let mut system = System::new_all();
        system.refresh_all();

        Self {
            config,
            system: Arc::new(RwLock::new(system)),
            networks: Arc::new(RwLock::new(Networks::new_with_refreshed_list())),
            disks: Arc::new(RwLock::new(Disks::new_with_refreshed_list())),
        }
    }

    /// Collect a single snapshot of all metrics.
    pub async fn collect(&self) -> Result<SystemSnapshot, MetricsError> {
        // Refresh all system info
        {
            let mut sys = self.system.write().await;
            sys.refresh_cpu_all();
            sys.refresh_memory();
        }

        let cpu = self.collect_cpu().await?;
        let memory = self.collect_memory().await?;
        let disk = self.collect_disk().await?;
        let network = self.collect_network().await?;

        Ok(SystemSnapshot {
            timestamp: Utc::now(),
            cpu,
            memory,
            disk,
            network,
        })
    }

    /// Collect CPU metrics.
    async fn collect_cpu(&self) -> Result<CpuMetrics, MetricsError> {
        let sys = self.system.read().await;

        let usage_percent = sys.global_cpu_usage();
        let core_count = sys.cpus().len();

        let per_core_usage = if self.config.per_core_metrics {
            sys.cpus().iter().map(|c| c.cpu_usage()).collect()
        } else {
            vec![]
        };

        let frequency_mhz = sys.cpus().first().map(|c| c.frequency());
        let brand = sys
            .cpus()
            .first()
            .map(|c| c.brand().to_string())
            .unwrap_or_else(|| "Unknown".to_string());

        Ok(CpuMetrics {
            usage_percent,
            per_core_usage,
            core_count,
            frequency_mhz,
            brand,
        })
    }

    /// Collect memory metrics.
    async fn collect_memory(&self) -> Result<super::metrics::MemoryMetrics, MetricsError> {
        let sys = self.system.read().await;

        let total_bytes = sys.total_memory();
        let used_bytes = sys.used_memory();
        let available_bytes = sys.available_memory();
        let swap_bytes = sys.total_swap();

        let usage_percent = if total_bytes > 0 {
            (used_bytes as f64 / total_bytes as f64 * 100.0) as f32
        } else {
            0.0
        };

        Ok(super::metrics::MemoryMetrics {
            total_bytes,
            used_bytes,
            available_bytes,
            usage_percent,
            swap_bytes,
        })
    }

    /// Collect disk metrics.
    async fn collect_disk(&self) -> Result<DiskMetrics, MetricsError> {
        let disks = self.disks.read().await;

        let disk_infos: Vec<DiskInfo> = disks
            .iter()
            .map(|d| {
                let total = d.total_space();
                let available = d.available_space();
                let used = total.saturating_sub(available);
                let usage_percent = if total > 0 {
                    (used as f64 / total as f64 * 100.0) as f32
                } else {
                    0.0
                };

                DiskInfo {
                    mount_point: d.mount_point().to_string_lossy().to_string(),
                    fs_type: d.file_system().to_string_lossy().to_string(),
                    total_bytes: total,
                    used_bytes: used,
                    available_bytes: available,
                    usage_percent,
                }
            })
            .collect();

        Ok(DiskMetrics { disks: disk_infos })
    }

    /// Collect network metrics.
    async fn collect_network(&self) -> Result<NetworkMetrics, MetricsError> {
        if !self.config.network_tracking {
            return Ok(NetworkMetrics {
                interfaces: vec![],
            });
        }

        let networks = self.networks.read().await;

        let interfaces: Vec<NetworkInterface> = networks
            .iter()
            .map(|(name, data)| NetworkInterface {
                name: name.clone(),
                rx_bytes: data.total_received(),
                tx_bytes: data.total_transmitted(),
                rx_packets: data.total_packets_received(),
                tx_packets: data.total_packets_transmitted(),
                rx_errors: data.total_errors_on_received(),
                tx_errors: data.total_errors_on_transmitted(),
            })
            .collect();

        Ok(NetworkMetrics { interfaces })
    }

    /// Get the configuration.
    pub fn config(&self) -> &CollectorConfig {
        &self.config
    }

    /// Create a background task that periodically collects metrics.
    pub fn spawn_collector<F>(&self, mut interval: Interval, mut callback: F)
    where
        F: FnMut(SystemSnapshot) + Send + 'static,
    {
        let collector = Arc::new(self.clone_inner());

        tokio::spawn(async move {
            loop {
                interval.tick().await;
                match collector.collect().await {
                    Ok(snapshot) => callback(snapshot),
                    Err(e) => {
                        tracing::warn!("metrics collection failed: {}", e);
                    }
                }
            }
        });
    }

    /// Clone the collector for spawning tasks.
    fn clone_inner(&self) -> Self {
        Self {
            config: self.config.clone(),
            system: Arc::clone(&self.system),
            networks: Arc::clone(&self.networks),
            disks: Arc::clone(&self.disks),
        }
    }
}

impl Default for MetricsCollector {
    fn default() -> Self {
        Self::new()
    }
}

impl Clone for MetricsCollector {
    fn clone(&self) -> Self {
        self.clone_inner()
    }
}

//! VIL System Metrics Plugin.
//!
//! Provides a VIL-compatible plugin for system metrics collection.
//! Integrates with VIL's state management and can serve metrics via HTTP.

use super::collector::{CollectorConfig, MetricsCollector};
use super::error::MetricsError;
use super::metrics::SystemSnapshot;
use dashmap::DashMap;
use std::sync::Arc;
use tokio::sync::RwLock;

/// Plugin configuration.
#[derive(Debug, Clone)]
pub struct PluginConfig {
    /// Collector configuration.
    pub collector: CollectorConfig,
    /// How many snapshots to keep in memory.
    pub retention_count: usize,
    /// Whether to enable the HTTP endpoint.
    pub http_endpoint: bool,
}

impl Default for PluginConfig {
    fn default() -> Self {
        Self {
            collector: CollectorConfig::default(),
            retention_count: 100,
            http_endpoint: true,
        }
    }
}

/// VIL System Metrics Plugin.
/// 
/// This plugin provides:
/// - Background metrics collection
/// - In-memory metrics history
/// - HTTP endpoint for metrics retrieval
/// - Integration with VIL state management
pub struct SystemMetricsPlugin {
    config: PluginConfig,
    collector: MetricsCollector,
    history: Arc<DashMap<u64, SystemSnapshot>>,
    latest: Arc<RwLock<Option<SystemSnapshot>>>,
}

impl SystemMetricsPlugin {
    /// Create a new plugin with default configuration.
    pub fn new() -> Self {
        Self::with_config(PluginConfig::default())
    }

    /// Create a new plugin with custom configuration.
    pub fn with_config(config: PluginConfig) -> Self {
        Self {
            config: config.clone(),
            collector: MetricsCollector::with_config(config.collector),
            history: Arc::new(DashMap::new()),
            latest: Arc::new(RwLock::new(None)),
        }
    }

    /// Get the metrics collector for custom usage.
    pub fn collector(&self) -> &MetricsCollector {
        &self.collector
    }

    /// Get the latest metrics snapshot.
    pub async fn latest(&self) -> Option<SystemSnapshot> {
        self.latest.read().await.clone()
    }

    /// Get metrics history (most recent first).
    pub fn history(&self, count: usize) -> Vec<SystemSnapshot> {
        self.history
            .iter()
            .take(count)
            .map(|r| r.value().clone())
            .collect()
    }

    /// Start background collection.
    pub fn start_collection(&self) {
        let collector = self.collector.clone();
        let history = Arc::clone(&self.history);
        let latest = Arc::clone(&self.latest);
        let retention_count = self.config.retention_count;

        tokio::spawn(async move {
            let mut interval = tokio::time::interval(collector.config().poll_interval);

            loop {
                interval.tick().await;
                match collector.collect().await {
                    Ok(snapshot) => {
                        // Update latest
                        {
                            let mut latest_guard = latest.write().await;
                            *latest_guard = Some(snapshot.clone());
                        }

                        // Add to history
                        let ts = snapshot.timestamp.timestamp() as u64;
                        history.insert(ts, snapshot);

                        // Trim old entries
                        if history.len() > retention_count {
                            // Remove oldest entries
                            let keys: Vec<_> = history.iter().map(|r| *r.key()).collect();
                            for key in keys.iter().take(history.len() - retention_count) {
                                history.remove(key);
                            }
                        }
                    }
                    Err(e) => {
                        tracing::warn!("metrics collection failed: {}", e);
                    }
                }
            }
        });
    }

    /// Get all current metrics as JSON string.
    pub async fn to_json(&self) -> Result<String, MetricsError> {
        match self.latest().await {
            Some(snapshot) => serde_json::to_string_pretty(&snapshot)
                .map_err(|e| MetricsError::CollectionFailed(e.to_string())),
            None => Ok("{}".to_string()),
        }
    }

    /// Get summary metrics (useful for dashboard display).
    pub async fn summary(&self) -> Option<MetricsSummary> {
        let latest = self.latest().await?;
        Some(MetricsSummary {
            cpu_percent: latest.cpu.usage_percent,
            memory_percent: latest.memory.usage_percent,
            disk_count: latest.disk.disks.len(),
            network_count: latest.network.interfaces.len(),
            timestamp: latest.timestamp,
        })
    }
}

impl Default for SystemMetricsPlugin {
    fn default() -> Self {
        Self::new()
    }
}

/// Summary metrics for quick display.
#[derive(Debug, serde::Serialize)]
pub struct MetricsSummary {
    /// CPU usage percentage.
    pub cpu_percent: f32,
    /// Memory usage percentage.
    pub memory_percent: f32,
    /// Number of disks tracked.
    pub disk_count: usize,
    /// Number of network interfaces tracked.
    pub network_count: usize,
    /// Timestamp of the snapshot.
    pub timestamp: chrono::DateTime<chrono::Utc>,
}

#[cfg(feature = "vil_integration")]
mod vil_integration {
    //! VIL integration module.
    //!
    //! Provides integration with VIL server applications.
    //!
    //! Note: This feature requires vil_server to be available.
    //! When enabled, the plugin registers with the VIL app.

    use super::*;

    /// Extension trait for VIL app integration.
    pub trait VilAppExt {
        /// Add the system metrics plugin.
        fn with_metrics(self) -> Self;
    }

    // Implementation would go here when vil_server is available
    // This provides a pattern for future integration
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_collector() {
        let collector = MetricsCollector::new();
        let snapshot = collector.collect().await.unwrap();

        println!("CPU: {}%", snapshot.cpu.usage_percent);
        println!("Memory: {}%", snapshot.memory.usage_percent);
        println!("Disks: {}", snapshot.disk.disks.len());
        println!("Networks: {}", snapshot.network.interfaces.len());
    }

    #[tokio::test]
    async fn test_plugin() {
        let plugin = SystemMetricsPlugin::new();
        plugin.start_collection();

        // Wait for first collection
        tokio::time::sleep(std::time::Duration::from_secs(1)).await;

        let latest = plugin.latest().await;
        assert!(latest.is_some());

        let summary = plugin.summary().await;
        assert!(summary.is_some());

        println!("Summary: {:?}", summary.unwrap());
    }
}

